/// <reference types="vite/client" />

interface ImportMetaEnv {
  // .env.local, generated by Rayfin
  readonly VITE_PORT?: string;
  readonly VITE_FABRIC_TENANT_ID?: string;
  readonly VITE_FABRIC_PORTAL_URL?: string;
  // .env, the app's own
  readonly VITE_MSAL_CLIENT_ID?: string;
  readonly VITE_MSAL_TENANT_ID?: string;
  readonly VITE_DEFAULT_WORKSPACE_ID?: string;
  readonly VITE_WARN_WORKSPACES?: string;
  readonly VITE_DEMO_MODE?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

declare module 'virtual:help' {
  const bundle: import('../tools/helpbuild.ts').HelpBundle;
  export default bundle;
}
